Here's the workaround:#21228

Update the function in`llama.cpp/common/chat-auto-parser-generator.cpp`(you can just replace the current function to this snippet)

```
common_chat_params peg_generator::generate_parser(const common_chat_template &    tmpl,
                                                  const struct generation_params & inputs,
                                                  const autoparser &              autoparser) {
    // Create a mutable copy to resolve refs before building the parser
    struct generation_params inputs_resolved = inputs;
    if (inputs_resolved.json_schema.is_object() && !inputs_resolved.json_schema.empty()) {
        // Inline $defs into $ref locations
        json schema_copy = inputs_resolved.json_schema;
        if (schema_copy.contains("$defs")) {
            json defs = schema_copy["$defs"];
            // First resolve nested $refs within $defs
            std::function<void(json&)> resolve_refs_inline = [&](json& n) {
                if (n.is_array()) {
                    for (auto &x : n) resolve_refs_inline(x);
                } else if (n.is_object()) {
                    if (n.contains("$ref") && n["$ref"].is_string()) {
                        std::string ref = n["$ref"].get<std::string>();
                        if (ref.find("#/$defs/") == 0) {
                            std::string def_name = ref.substr(8);
                            if (defs.contains(def_name)) {
                                n = defs[def_name];
                            }
                        }
                    } else {
                        for (const auto &kv : n.items()) resolve_refs_inline(kv.value());
                    }
                }
            };
            // Resolve within $defs first
            for (const auto &kv : defs.items()) {
                resolve_refs_inline(kv.value());
            }
            // Then resolve in the rest of the schema
            resolve_refs_inline(schema_copy);
            schema_copy.erase("$defs");
        }
        inputs_resolved.json_schema = schema_copy;
    }

    // Create the result structure
    common_chat_params data;
    data.prompt           = common_chat_template_direct_apply(tmpl, inputs_resolved);
    data.format           = COMMON_CHAT_FORMAT_PEG_NATIVE;
    data.preserved_tokens = autoparser.preserved_tokens;

    auto parser = autoparser.build_parser(inputs_resolved);
    data.parser = parser.save();

    // Build grammar if tools are present
    bool has_tools =
        autoparser.tools.format.mode != tool_format::NONE && inputs_resolved.tools.is_array() && !inputs_resolved.tools.empty();
    std::string trigger_marker = !autoparser.tools.format.section_start.empty() ? autoparser.tools.format.section_start :
                                                                                  autoparser.tools.format.per_call_start;

    bool has_response_format = !inputs_resolved.json_schema.empty() && inputs_resolved.json_schema.is_object();
    bool include_grammar = has_response_format || (has_tools &&
            ((inputs_resolved.tool_choice == COMMON_CHAT_TOOL_CHOICE_AUTO && !trigger_marker.empty()) ||
              inputs_resolved.tool_choice == COMMON_CHAT_TOOL_CHOICE_REQUIRED));

    if (include_grammar) {
        data.grammar_lazy = !has_response_format && inputs_resolved.tool_choice == COMMON_CHAT_TOOL_CHOICE_AUTO;
        data.grammar      = build_grammar([&](const common_grammar_builder & builder) {
            foreach_function(inputs_resolved.tools, [&](const json & tool) {
                const auto & function = tool.at("function");
                auto         schema   = function.contains("parameters") ? function.at("parameters") : json::object();
                builder.resolve_refs(schema);
            });
            parser.build_grammar(builder, data.grammar_lazy);
        });

        // Set grammar triggers based on tool section markers (fall back to per-call markers)
        if (data.grammar_lazy) {
            data.grammar_triggers = {
                { COMMON_GRAMMAR_TRIGGER_TYPE_WORD, trigger_marker }
            };
        }
    }

    return data;
}
```

